function fibLike(n) {
  if (n < 2) {
    return n;
  }
  return fibLike(n - 1) + fibLike(n - 2);
}

function totalEvens(xs) {
  let total = 0;
  for (let i = 0; i < xs.length; i++) {
    if (xs[i] % 2 === 0) {
      total += xs[i];
    }
  }
  return total;
}

function firstIndex(xs, target) {
  let i = 0;
  while (i < xs.length) {
    if (xs[i] === target) {
      return i;
    }
    i += 1;
  }
  return -1;
}

function squaresOver(xs, k) {
  return xs.filter(function (x) {
    return x > k;
  }).map(function (x) {
    return x * x;
  });
}

function countChars(s) {
  const counts = {};
  for (const ch of s) {
    counts[ch] = (counts[ch] || 0) + 1;
  }
  return counts;
}

function shoutWords(s) {
  const parts = s.split(" ");
  const out = [];
  for (const p of parts) {
    if (p) {
      out.push(p.toUpperCase());
    }
  }
  return out.join("-");
}

function applyTwice(n) {
  function bump(v) {
    return v * 2 + 1;
  }
  return bump(bump(n));
}

function pairSums(xs) {
  const out = [];
  for (let i = 0; i < xs.length; i++) {
    for (let j = i + 1; j < xs.length; j++) {
      out.push(xs[i] + xs[j]);
    }
  }
  return out;
}

function untilNegative(xs) {
  const out = [];
  for (const x of xs) {
    if (x === 0) {
      continue;
    }
    if (x < 0) {
      break;
    }
    out.push(x);
  }
  return out;
}

function scale(v, factor) {
  return v * factor;
}

function normalizeAll(xs) {
  let biggest = 0;
  for (const x of xs) {
    if (x > biggest) {
      biggest = x;
    }
  }
  if (biggest === 0) {
    return [];
  }
  return xs.map(function (x) {
    return Math.floor(scale(x, 100) / biggest);
  });
}
